INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5221ef8e-19e0-50a0-91c3-a4bdbbfd1591', '1271e5db-e806-5e63-9a37-ea132a1c751f', NULL, 'Галина Х.', 'COUPLE', 7.0, '2025-05-01', 'Есть над чем поработать', 'Море прозрачное, как в бассейне. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+еда', '-рельеф'], '2025-06-15T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('103443cf-8628-5032-a610-09001799659a', '1271e5db-e806-5e63-9a37-ea132a1c751f', NULL, 'Анна О.', 'SENIORS', 6.5, '2025-08-01', 'На один раз', 'Море прозрачное, как в бассейне. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Тихо, ночью ничего не слышно — отлично выспались.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. В августе у берега было много медуз, пару дней купались только в бассейне. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '-медузы', '+еда', '+тишина', '-рельеф'], '2025-08-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('434c58b7-15d8-502a-95d1-96574ddffe5c', '1271e5db-e806-5e63-9a37-ea132a1c751f', NULL, 'Виктория Г.', 'SENIORS', 7.0, '2025-07-01', 'Ожидали большего', 'Вода кристально чистая, на глубине видно каждый камень. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+еда', '-рельеф'], '2025-07-19T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('e0c6ae67-b140-5dd6-806f-548f3bdf52d1', '1271e5db-e806-5e63-9a37-ea132a1c751f', NULL, 'Елена Ч.', 'SOLO', 8.5, '2026-01-01', 'В целом всё отлично', 'Вода кристально чистая, на глубине видно каждый камень. СПА отличное, массаж — лучший за поездку. Ужины вкусные, есть детское меню. Хорошая шумоизоляция, спали с открытым балконом. Wi-Fi быстрый, без проблем работал из номера. Персонал приветливый, любые вопросы решали быстро.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет.', ARRAY['+пляж', '-галька', '-глубина', '+СПА', '+еда', '+тишина', '+Wi-Fi', '+персонал'], '2026-02-07T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('54f60dac-64c3-5671-bdb9-ad5af8057acb', '13a1f5f2-83fc-57e3-9dc1-2538706bd291', NULL, 'Татьяна К.', 'FAMILY', 8.0, '2026-05-01', 'В целом всё отлично', 'Вода кристально чистая, на глубине видно каждый камень. СПА отличное, массаж — лучший за поездку. На завтрак местная кухня — пробовали каждый день что-то новое. На ресепшене помогли с экскурсиями и такси.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '-галька', '-глубина', '+СПА', '+еда', '-шум', '+персонал'], '2026-05-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('42a0143b-b085-5e82-8f70-89af36b5e28d', '13a1f5f2-83fc-57e3-9dc1-2538706bd291', NULL, 'Артём Л.', 'FAMILY', 7.0, '2025-10-01', 'Ожидали большего', 'Море прозрачное, как в бассейне.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Пыль под кроватью и на балконе, пришлось просить убрать. Слышимость хорошая — соседей слышно, берите беруши.', ARRAY['+пляж', '-галька', '-глубина', '-уборка', '-шум'], '2025-10-24T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8148a1ec-e54c-5a8b-919b-517067370bf5', '13a1f5f2-83fc-57e3-9dc1-2538706bd291', NULL, 'Ляйсан М.', 'SENIORS', 7.5, '2025-06-01', 'Достойно за свои деньги', 'Море прозрачное, как в бассейне. СПА отличное, массаж — лучший за поездку. Ездили с мамой на коляске: пандусы, лифт, в номере поручни и душ без поддона. Персонал приветливый, любые вопросы решали быстро.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Пыль под кроватью и на балконе, пришлось просить убрать. Ночью шумно: музыка с улицы до двух часов. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+СПА', '-уборка', '-шум', '-рельеф', '+доступность', '+персонал'], '2025-06-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('c56bc9f6-d017-541a-beda-f2331239adef', '13a1f5f2-83fc-57e3-9dc1-2538706bd291', NULL, 'Екатерина Р.', 'FRIENDS', 6.5, '2026-09-01', 'Ожидали большего', 'Море прозрачное, как в бассейне. СПА отличное, массаж — лучший за поездку. На завтрак местная кухня — пробовали каждый день что-то новое.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В сентябре у берега было много медуз, пару дней купались только в бассейне. Уборка так себе: полотенца меняли через раз. Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '-галька', '-глубина', '-медузы', '+СПА', '+еда', '-уборка', '-шум'], '2026-09-11T12:00:00+03:00');
