INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('503152da-637a-5723-acc8-a6e6f9772ba0', '1f712cbb-3f1e-5985-81a0-ae6ef3935299', NULL, 'Наталья Р.', 'COUPLE', 8.5, '2025-05-01', 'Хороший отдых', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Номер убирали каждый день, бельё меняли без напоминаний. Тихо, ночью ничего не слышно — отлично выспались.', 'Wi-Fi слабый, в номере почти не ловит.', ARRAY['+еда', '+чистота', '+тишина', '-Wi-Fi'], '2025-05-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('136110a1-a671-52e0-87f0-4a2b9833da5e', '1f712cbb-3f1e-5985-81a0-ae6ef3935299', NULL, 'Роман У.', 'BUSINESS', 8.5, '2026-05-01', 'Рекомендую, но с оговорками', 'Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Везде чисто — и в номере, и у бассейна. Хорошая шумоизоляция, спали с открытым балконом. На ресепшене помогли с экскурсиями и такси.', 'Wi-Fi слабый, в номере почти не ловит.', ARRAY['+еда', '+чистота', '+тишина', '-Wi-Fi', '+персонал'], '2026-05-28T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('232ec50f-77d1-552f-8e36-34aba5033fd3', '1f712cbb-3f1e-5985-81a0-ae6ef3935299', NULL, 'Екатерина Г.', 'SENIORS', 8.0, '2025-05-01', 'Достойно за свои деньги', 'На завтрак местная кухня — пробовали каждый день что-то новое. Чистота идеальная, придраться не к чему. Тихо, ночью ничего не слышно — отлично выспались.', 'Wi-Fi слабый, в номере почти не ловит. Лифта нет — с чемоданами и пожилыми родителями тяжело.', ARRAY['+еда', '+чистота', '+тишина', '-Wi-Fi', '-нет лифта'], '2025-05-23T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('129ddb11-a8a5-5bb9-87de-52f8474a6ede', '1f712cbb-3f1e-5985-81a0-ae6ef3935299', NULL, 'Алина Ф.', 'BUSINESS', 8.5, '2025-07-01', 'Рекомендую, но с оговорками', 'Номер убирали каждый день, бельё меняли без напоминаний. Очень спокойно, слышно только птиц и море. На ресепшене помогли с экскурсиями и такси.', 'Wi-Fi слабый, в номере почти не ловит.', ARRAY['+чистота', '+тишина', '-Wi-Fi', '+персонал'], '2025-07-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('36d79473-05d8-58f2-860d-c04755a8e7bd', '24d6612b-1160-5f29-bbeb-61eb0a4173be', NULL, 'Виктория Н.', 'FAMILY', 7.0, '2025-11-01', 'На один раз', 'Галька мелкая и чистая, море без мути даже после ветра. Ужины вкусные, есть детское меню. Чистота идеальная, придраться не к чему.', 'Слышимость хорошая — соседей слышно, берите беруши. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+пляж', '+еда', '+чистота', '-шум', '-Wi-Fi'], '2025-11-19T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('99357e2e-b71d-5127-87cd-af3567bf82a7', '24d6612b-1160-5f29-bbeb-61eb0a4173be', NULL, 'Никита А.', 'COUPLE', 8.0, '2025-10-01', 'Хороший отдых', 'Мелкая галька, вода прозрачная — видно дно. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Номер убирали каждый день, бельё меняли без напоминаний.', 'Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '+еда', '+чистота', '-шум'], '2025-11-11T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('086fab6a-4fbc-592a-9ec5-9630b1810869', '24d6612b-1160-5f29-bbeb-61eb0a4173be', NULL, 'Дмитрий Ф.', 'COUPLE', 6.5, '2025-07-01', 'На один раз', 'Галька мелкая и чистая, море без мути даже после ветра. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Чистота идеальная, придраться не к чему.', 'В июле у берега было много медуз, пару дней купались только в бассейне. Ночью шумно: музыка с улицы до двух часов. Wi-Fi слабый, в номере почти не ловит.', ARRAY['+пляж', '-медузы', '+еда', '+чистота', '-шум', '-Wi-Fi'], '2025-08-13T12:00:00+03:00');
