INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('18c44e75-eed9-52c4-8cc9-716a4ea7d076', '38b231f7-1429-533e-a00c-c112301c2ac6', NULL, 'Ляйсан Л.', 'COUPLE', 7.5, '2025-06-01', 'Рекомендую, но с оговорками', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. На завтрак местная кухня — пробовали каждый день что-то новое. Номер убирали каждый день, бельё меняли без напоминаний.', 'Экскурсии в отеле дороже, чем у местных агентств.', ARRAY['+пляж', '+еда', '+чистота', '-цены'], '2025-06-27T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8df2cf1f-157d-59fc-aeea-6a61a07c7559', '38b231f7-1429-533e-a00c-c112301c2ac6', NULL, 'Ляйсан Х.', 'FRIENDS', 8.0, '2025-07-01', 'Рекомендую, но с оговорками', 'Городской пляж Махачкалы рядом — песок чистый, лежаки бесплатные. Чистота идеальная, придраться не к чему.', 'Ремонт в номере местами староват.', ARRAY['+пляж', '+чистота', '-ремонт'], '2025-07-31T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('95080dd8-0f37-5ba8-945b-fa6472b884d9', '38b231f7-1429-533e-a00c-c112301c2ac6', NULL, 'Тимур Т.', 'FAMILY', 8.5, '2026-08-01', 'Рекомендую, но с оговорками', 'Городской пляж Махачкалы рядом — песок чистый, лежаки бесплатные. Мелководье у берега — сын строил замки и плавал в нарукавниках без страха. Завтраки вкусные, кофе нормальный, а не из автомата. Номер убирали каждый день, бельё меняли без напоминаний. На ресепшене помогли с экскурсиями и такси.', 'Цены в баре и ресторане кусаются.', ARRAY['+пляж', '+детям', '+еда', '+чистота', '-цены', '+персонал'], '2026-08-21T12:00:00+03:00');
