INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('dc58da64-9ed6-5825-a659-bc0407230a3b', '7b404629-c475-52c5-9e03-cc45c202a6a1', NULL, 'Ксения Ш.', 'FAMILY', 7.5, '2025-11-01', 'Рекомендую, но с оговорками', 'Галька мелкая и чистая, море без мути даже после ветра. Очень спокойно, слышно только птиц и море.', 'Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '+тишина', '-рельеф'], '2025-12-07T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('6e33e417-a77c-5116-8661-1c45ead924de', '7b404629-c475-52c5-9e03-cc45c202a6a1', NULL, 'Владимир А.', 'SOLO', 7.5, '2025-09-01', 'Рекомендую, но с оговорками', 'Мелкая галька, вода прозрачная — видно дно. Завтраки вкусные, кофе нормальный, а не из автомата. Везде чисто — и в номере, и у бассейна. Хорошая шумоизоляция, спали с открытым балконом. Персонал приветливый, любые вопросы решали быстро.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+пляж', '+еда', '+чистота', '+тишина', '-ремонт', '+персонал'], '2025-10-12T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('c644c670-9cba-5e23-b166-6137d8cef688', '7c50a511-b636-56cc-94cc-1ea2195dacdd', NULL, 'Сергей Т.', 'FRIENDS', 9.0, '2026-06-01', 'Всё понравилось', 'Номер убирали каждый день, бельё меняли без напоминаний. Расположение супер: всё главное — пешком.', NULL, ARRAY['+чистота', '+расположение'], '2026-06-24T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('37609501-8af2-5ae9-8d71-8419e0cf1d12', '7c50a511-b636-56cc-94cc-1ea2195dacdd', NULL, 'Людмила Л.', 'COUPLE', 8.5, '2025-08-01', 'В целом всё отлично', 'На завтрак местная кухня — пробовали каждый день что-то новое. Номер убирали каждый день, бельё меняли без напоминаний. Очень спокойно, слышно только птиц и море. Расположение супер: всё главное — пешком.', 'Дорога из аэропорта долгая — около 2 ч.', ARRAY['+еда', '+чистота', '+тишина', '+расположение', '-трансфер'], '2025-09-12T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8be1aae6-74a6-5df1-8d6a-132471e805b4', '7c50a511-b636-56cc-94cc-1ea2195dacdd', NULL, 'Анна Р.', 'SENIORS', 9.0, '2025-08-01', 'Отдых мечты', 'Завтраки вкусные, кофе нормальный, а не из автомата. Номер убирали каждый день, бельё меняли без напоминаний. Очень спокойно, слышно только птиц и море. Центр рядом, гуляли пешком целыми днями. Персонал приветливый, любые вопросы решали быстро.', 'Лифта нет — с чемоданами и пожилыми родителями тяжело.', ARRAY['+еда', '+чистота', '+тишина', '+расположение', '-нет лифта', '+персонал'], '2025-09-18T12:00:00+03:00');
