INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('cd58e974-3047-5fed-a284-1892c71ba7b9', '853c922d-381a-5508-a43c-aa4efb2d7e26', NULL, 'Сергей Г.', 'SOLO', 9.0, '2025-04-01', 'Отдых мечты', 'Песок мягкий, вода прозрачная, к морю пара минут. СПА отличное, массаж — лучший за поездку. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным.', 'Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '+СПА', '+еда', '-уборка'], '2025-05-01T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('fdbb2450-3a1c-59d5-a5b8-eae1aa51244e', '853c922d-381a-5508-a43c-aa4efb2d7e26', NULL, 'Екатерина У.', 'SOLO', 7.0, '2025-07-01', 'Ожидали большего', 'Пляжи Евпатории рядом — песок чистый, лежаки бесплатные. Ветер почти каждый день — для кайта то что надо.', 'В разгар сезона на пляже тесно, лежаки занимают с утра. В июле у берега было много медуз, пару дней купались только в бассейне. Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+пляж', '-толпы', '+кайт', '-медузы', '-уборка'], '2025-07-25T12:00:00+03:00');
