INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('30fb38cc-e3fe-575d-97e0-f897c00cdad9', '950f2ba8-9f8a-54af-9c13-549488de4023', NULL, 'Ирина Я.', 'COUPLE', 8.5, '2025-10-01', 'В целом всё отлично', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. На завтрак местная кухня — пробовали каждый день что-то новое. На ресепшене помогли с экскурсиями и такси.', 'Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '+еда', '-шум', '+персонал'], '2025-10-30T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('f4a5b91c-18f6-5a58-8348-c3baee99225f', '950f2ba8-9f8a-54af-9c13-549488de4023', NULL, 'Галина П.', 'FRIENDS', 8.5, '2025-05-01', 'В целом всё отлично', 'Песок мягкий, вода прозрачная, к морю пара минут. Завтраки вкусные, кофе нормальный, а не из автомата.', 'Слышимость хорошая — соседей слышно, берите беруши.', ARRAY['+пляж', '+еда', '-шум'], '2025-06-11T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('a89eb50f-c91a-55cf-a2d7-d5c90e5ef87f', '9b457e00-63a1-5dc0-bb32-5c9a9ee4da64', NULL, 'Алина К.', 'SOLO', 7.5, '2025-04-01', 'Хороший отдых', 'Вода кристально чистая, на глубине видно каждый камень. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Wi-Fi быстрый, без проблем работал из номера.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '+еда', '+Wi-Fi'], '2025-05-15T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('347220d3-d188-5aa7-b460-4474efdf3794', '9b457e00-63a1-5dc0-bb32-5c9a9ee4da64', NULL, 'Мария Ш.', 'SOLO', 7.0, '2026-04-01', 'На один раз', 'Море прозрачное, как в бассейне. Взяли маски — у камней полно рыбы. СПА отличное, массаж — лучший за поездку. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Wi-Fi быстрый, без проблем работал из номера.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '+СПА', '+еда', '+Wi-Fi', '-рельеф'], '2026-04-21T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('f3f0bacc-e436-5e50-921d-e662a0b16a04', '9b457e00-63a1-5dc0-bb32-5c9a9ee4da64', NULL, 'Артём Е.', 'SENIORS', 6.5, '2025-06-01', 'Ожидали большего', 'Море прозрачное, как в бассейне. Взяли маски — у камней полно рыбы. Ужины вкусные, есть детское меню.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '+еда', '-рельеф'], '2025-06-18T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('a8d59b76-fbbe-5170-bde8-1db299e4b63e', '9b457e00-63a1-5dc0-bb32-5c9a9ee4da64', NULL, 'Галина Г.', 'COUPLE', 6.5, '2026-09-01', 'Есть над чем поработать', 'Вода кристально чистая, на глубине видно каждый камень. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В сентябре у берега было много медуз, пару дней купались только в бассейне.', ARRAY['+пляж', '-галька', '-глубина', '-медузы', '+еда'], '2026-09-16T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('30973aa8-0bb1-5ee1-bcd5-12e0aa628c73', '9b62173d-4a4c-5d55-827e-13a8619f16e0', NULL, 'Ирина К.', 'COUPLE', 8.0, '2026-03-01', 'В целом всё отлично', 'На завтрак местная кухня — пробовали каждый день что-то новое. Центр рядом, гуляли пешком целыми днями.', 'Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+еда', '-уборка', '+расположение'], '2026-03-27T12:00:00+03:00');
