INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('098f3d14-2286-5da2-a240-15afc4a93482', 'a1c4135a-13b2-5c69-8550-eb78876af2b4', NULL, 'Дмитрий Х.', 'FAMILY', 8.5, '2025-10-01', 'Хороший отдых', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Мелководье у берега — сын строил замки и плавал в нарукавниках без страха. Ужины вкусные, есть детское меню. Персонал приветливый, любые вопросы решали быстро.', 'Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+пляж', '+детям', '+еда', '-уборка', '+персонал'], '2025-11-02T12:00:00+03:00');
