INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('e261f7cd-b45a-5e76-a4e4-8cd8d779daa3', 'c0a22fad-b12c-5717-9efc-45d786cfd4de', NULL, 'Алексей Ш.', 'SOLO', 8.5, '2026-03-01', 'Достойно за свои деньги', 'СПА отличное, массаж — лучший за поездку. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. Центр рядом, гуляли пешком целыми днями. На ресепшене помогли с экскурсиями и такси.', 'Wi-Fi слабый, в номере почти не ловит.', ARRAY['+СПА', '+еда', '-Wi-Fi', '+расположение', '+персонал'], '2026-03-28T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('94fb6aa7-9968-596d-8835-e65ce1852130', 'c15f465b-e556-5fdf-ad37-a114f01e0521', NULL, 'Алексей Я.', 'FAMILY', 9.0, '2025-06-01', 'Всё понравилось', 'Мелкая галька, вода прозрачная — видно дно. Вход в воду пологий, ребёнок часами плескался у берега. На завтрак местная кухня — пробовали каждый день что-то новое. На ресепшене помогли с экскурсиями и такси.', 'Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '+детям', '+еда', '-шум', '+персонал'], '2025-07-08T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('ac27b054-115b-555a-bcde-0605d9debc2a', 'c15f465b-e556-5fdf-ad37-a114f01e0521', NULL, 'Олег Б.', 'COUPLE', 8.0, '2025-04-01', 'В целом всё отлично', 'Галька мелкая и чистая, море без мути даже после ветра. На завтрак местная кухня — пробовали каждый день что-то новое. Везде чисто — и в номере, и у бассейна. На ресепшене помогли с экскурсиями и такси.', 'Ночью шумно: музыка с улицы до двух часов.', ARRAY['+пляж', '+еда', '+чистота', '-шум', '+персонал'], '2025-05-08T12:00:00+03:00');
