INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('eee23355-c2b2-583a-b9f0-237e43163829', 'dcafd365-97a0-5bd8-9cda-cb6fa003723d', NULL, 'Евгений С.', 'COUPLE', 7.0, '2025-08-01', 'Есть над чем поработать', 'Вода кристально чистая, на глубине видно каждый камень. Взяли маски — у камней полно рыбы. На завтрак местная кухня — пробовали каждый день что-то новое. Персонал приветливый, любые вопросы решали быстро.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '+еда', '-уборка', '+персонал'], '2025-08-22T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5b1b7d87-8fda-5be9-985a-ad06d1685e08', 'dcafd365-97a0-5bd8-9cda-cb6fa003723d', NULL, 'Елена Х.', 'SENIORS', 7.0, '2025-09-01', 'Есть над чем поработать', 'Море прозрачное, как в бассейне. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи. Завтраки вкусные, кофе нормальный, а не из автомата.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Уборка так себе: полотенца меняли через раз. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '+еда', '-уборка', '-рельеф'], '2025-09-21T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('ed60a93f-5202-5c9c-b0ec-197ced32de26', 'dcafd365-97a0-5bd8-9cda-cb6fa003723d', NULL, 'Игорь Е.', 'FAMILY', 7.0, '2025-04-01', 'Есть над чем поработать', 'Вода кристально чистая, на глубине видно каждый камень. На завтрак местная кухня — пробовали каждый день что-то новое.', 'Галька крупная — без коралловых тапочек больно. Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '-галька', '-глубина', '+еда', '-уборка'], '2025-04-22T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('097916d5-4f04-59f9-aa00-970de647a39f', 'dcafd365-97a0-5bd8-9cda-cb6fa003723d', NULL, 'Ирина М.', 'SENIORS', 7.0, '2025-05-01', 'Есть над чем поработать', 'Вода кристально чистая, на глубине видно каждый камень. Снорклинг прямо с берега: рыбы-попугаи, иногда черепахи.', 'Галька крупная — без коралловых тапочек больно. К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. Пыль под кроватью и на балконе, пришлось просить убрать. Отель на склоне: вниз идти легко, а обратно в гору — тяжело, особенно в жару.', ARRAY['+пляж', '-галька', '-глубина', '+снорклинг', '-уборка', '-рельеф'], '2025-05-13T12:00:00+03:00');
