INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('d2d6eda6-0ade-57f0-8c08-b656a122cd68', 'e1b2dcd0-cc01-52d2-9eec-0032c5404215', NULL, 'Нурлан И.', 'FRIENDS', 9.0, '2025-05-01', 'Всё понравилось', 'Первый пляж Циндао рядом — песок чистый, лежаки бесплатные. На завтрак местная кухня — пробовали каждый день что-то новое. Персонал приветливый, любые вопросы решали быстро.', NULL, ARRAY['+пляж', '+еда', '+персонал'], '2025-05-23T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('7a64a090-b72e-5f25-a9fc-c3ea9a20b05c', 'e1b2dcd0-cc01-52d2-9eec-0032c5404215', NULL, 'Николай К.', 'SOLO', 8.5, '2026-08-01', 'Рекомендую, но с оговорками', 'Песок мягкий, вода прозрачная, к морю пара минут. Чистота идеальная, придраться не к чему. Wi-Fi быстрый, без проблем работал из номера. На ресепшене помогли с экскурсиями и такси.', 'В разгар сезона на пляже тесно, лежаки занимают с утра.', ARRAY['+пляж', '-толпы', '+чистота', '+Wi-Fi', '+персонал'], '2026-08-18T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('81f8d4b6-0575-50a4-98da-1b6883d19b96', 'e2fe516a-9441-58fb-a347-ae4ad3436830', NULL, 'Виктория Р.', 'COUPLE', 8.0, '2025-08-01', 'В целом всё отлично', 'Пляж отличный: мелкий песок, заходить в море одно удовольствие. Ужины вкусные, есть детское меню. Номер убирали каждый день, бельё меняли без напоминаний. Хорошая шумоизоляция, спали с открытым балконом.', 'В августе у берега было много медуз, пару дней купались только в бассейне. Дорога из аэропорта долгая — около 2 ч.', ARRAY['+пляж', '-медузы', '+еда', '+чистота', '+тишина', '-трансфер'], '2025-08-12T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('fb479e1b-8b4f-516d-924f-6aacc921947f', 'e2fe516a-9441-58fb-a347-ae4ad3436830', NULL, 'Полина О.', 'SOLO', 7.0, '2026-04-01', 'Ожидали большего', 'Песок мягкий, вода прозрачная, к морю пара минут. Чистота идеальная, придраться не к чему. Очень спокойно, слышно только птиц и море.', 'Wi-Fi слабый, в номере почти не ловит. Дорога из аэропорта долгая — около 2 ч.', ARRAY['+пляж', '+чистота', '+тишина', '-Wi-Fi', '-трансфер'], '2026-05-15T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('ae9eab03-05fd-503d-b13e-af1848458186', 'e2fe516a-9441-58fb-a347-ae4ad3436830', NULL, 'Никита Х.', 'FRIENDS', 7.0, '2025-04-01', 'Ожидали большего', 'Золотой пляж Феодосии рядом — песок чистый, лежаки бесплатные. Кормят разнообразно: рыба, фрукты, выпечка — никто не остался голодным. Тихо, ночью ничего не слышно — отлично выспались.', 'Wi-Fi слабый, в номере почти не ловит. Дорога из аэропорта долгая — около 2 ч.', ARRAY['+пляж', '+еда', '+тишина', '-Wi-Fi', '-трансфер'], '2025-04-28T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('be33f799-4246-5f09-9a99-da0d022ee02b', 'e2fe516a-9441-58fb-a347-ae4ad3436830', NULL, 'Галина В.', 'COUPLE', 8.0, '2025-04-01', 'Достойно за свои деньги', 'Песок мягкий, вода прозрачная, к морю пара минут. Ужины вкусные, есть детское меню. Номер убирали каждый день, бельё меняли без напоминаний. Тихо, ночью ничего не слышно — отлично выспались. Персонал приветливый, любые вопросы решали быстро.', 'Дорога из аэропорта долгая — около 2 ч.', ARRAY['+пляж', '+еда', '+чистота', '+тишина', '-трансфер', '+персонал'], '2025-04-25T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('e48f49ea-da79-5113-9226-ac88683ba3de', 'e4000819-6912-510a-a2a8-ba3855bb2f9a', NULL, 'Полина П.', 'COUPLE', 5.5, '2025-07-01', 'Ожидали большего', 'Мелкая галька, вода прозрачная — видно дно. Взяли маски — у камней полно рыбы.', 'К рифу заходили по понтону, дальше сразу глубоко. Для снорклинга супер, для малышей — нет. В разгар сезона на пляже тесно, лежаки занимают с утра. В июле у берега было много медуз, пару дней купались только в бассейне. Вода холоднее, чем ждали: зашёл — и сразу обратно. Пыль под кроватью и на балконе, пришлось просить убрать. Дорога из аэропорта долгая — около 1 ч.', ARRAY['+пляж', '-глубина', '-толпы', '+снорклинг', '-медузы', '-холодная вода', '-уборка', '-трансфер'], '2025-07-28T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('a904eb7a-59c9-5b5f-bb96-b93941370a3a', 'e4000819-6912-510a-a2a8-ba3855bb2f9a', NULL, 'Татьяна Ф.', 'FRIENDS', 7.5, '2026-09-01', 'Достойно за свои деньги', 'Мелкая галька, вода прозрачная — видно дно. Взяли маски — у камней полно рыбы. На завтрак местная кухня — пробовали каждый день что-то новое.', 'Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. В сентябре у берега было много медуз, пару дней купались только в бассейне. Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+пляж', '-глубина', '+снорклинг', '-медузы', '+еда', '-уборка'], '2026-09-22T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('34752b77-1fac-5a7c-a71e-6845ae912bf4', 'e4000819-6912-510a-a2a8-ba3855bb2f9a', NULL, 'Михаил Ш.', 'SENIORS', 7.5, '2026-02-01', 'Хороший отдых', 'Мелкая галька, вода прозрачная — видно дно. Завтраки вкусные, кофе нормальный, а не из автомата.', 'Глубина начинается почти сразу — детям и тем, кто плохо плавает, неуютно. Уборка так себе: полотенца меняли через раз.', ARRAY['+пляж', '-глубина', '+еда', '-уборка'], '2026-02-28T12:00:00+03:00');
