INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('5e0e38cf-6977-5c81-b6f7-b9433ba7eff3', 'edfb8b4f-017a-5adb-97d7-8b2b51afcedd', NULL, 'Алина Т.', 'COUPLE', 9.0, '2026-01-01', 'Отдых мечты', 'Очень спокойно, слышно только птиц и море. На ресепшене помогли с экскурсиями и такси.', 'Уборка так себе: полотенца меняли через раз.', ARRAY['-уборка', '+тишина', '+персонал'], '2026-01-17T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('0d4b02eb-30b4-5000-af5d-80165d5e34b7', 'edfb8b4f-017a-5adb-97d7-8b2b51afcedd', NULL, 'Евгений С.', 'COUPLE', 8.0, '2026-01-01', 'В целом всё отлично', 'На завтрак местная кухня — пробовали каждый день что-то новое. Персонал приветливый, любые вопросы решали быстро.', 'Уборка так себе: полотенца меняли через раз.', ARRAY['+еда', '-уборка', '+персонал'], '2026-01-23T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('fa315e7e-89ec-58c7-81d7-cea0f6a2a29f', 'edfb8b4f-017a-5adb-97d7-8b2b51afcedd', NULL, 'Светлана Я.', 'COUPLE', 9.0, '2025-01-01', 'Вернёмся ещё!', 'СПА отличное, массаж — лучший за поездку. Завтрак простой, но свежий: яйца на заказ, фрукты, выпечка. На ресепшене помогли с экскурсиями и такси.', 'Пыль под кроватью и на балконе, пришлось просить убрать.', ARRAY['+СПА', '+еда', '-уборка', '+персонал'], '2025-02-12T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('8fce27e5-470c-5ff1-adaa-422aa96c1b40', 'f8e8b9f9-92c3-57da-9548-57b04f5edf8a', NULL, 'Артём Х.', 'FRIENDS', 8.5, '2025-10-01', 'В целом всё отлично', 'Мелкая галька, вода прозрачная — видно дно. СПА отличное, массаж — лучший за поездку. Чистота идеальная, придраться не к чему. Очень спокойно, слышно только птиц и море. Персонал приветливый, любые вопросы решали быстро.', 'Сантехника не новая, кран в душе подтекал.', ARRAY['+пляж', '+СПА', '+чистота', '+тишина', '-ремонт', '+персонал'], '2025-11-11T12:00:00+03:00');
INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('6fb3d39a-0048-5076-a0ab-fbdadd4fe63f', 'f8e8b9f9-92c3-57da-9548-57b04f5edf8a', NULL, 'Владимир Х.', 'COUPLE', 8.5, '2025-09-01', 'В целом всё отлично', 'Мелкая галька, вода прозрачная — видно дно. СПА отличное, массаж — лучший за поездку. Завтраки вкусные, кофе нормальный, а не из автомата. Чистота идеальная, придраться не к чему. Хорошая шумоизоляция, спали с открытым балконом.', 'В сентябре у берега было много медуз, пару дней купались только в бассейне.', ARRAY['+пляж', '-медузы', '+СПА', '+еда', '+чистота', '+тишина'], '2025-10-07T12:00:00+03:00');
