INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('c3babe9e-90e0-5829-920c-cb94260b55f3', NULL, 'e81a6a22-bb24-5ce5-b450-d7dec109c21c', 'Ольга У.', 'FAMILY', 6.5, '2026-07-01', 'Ожидали другого', 'Покрытие — мелкая гладкая галька. У рифа невероятный снорклинг — свал уходит в синеву. Развлечения: лодки к Адаларам, SUP.', 'Глубоко почти сразу — детям и неуверенным пловцам осторожно. В высокий сезон очень людно, особенно в выходные. С маленькими детьми неудобно. В июле у берега было много медуз, пару дней купались только в бассейне. Вода холоднее, чем ждали: зашёл — и сразу обратно.', ARRAY['+пляж', '-глубина', '+снорклинг', '-толпы', '+развлечения', '-детям', '-медузы', '-холодная вода'], '2026-07-12T12:00:00+03:00');
