INSERT INTO review (id, hotel_id, beach_id, author, trip_type, rating, stayed_on, title, pros, cons, tags, created_at) VALUES ('9cb7dd8b-ab20-52bf-b093-dc41d9eaa31a', NULL, 'ad97f2c9-d0f6-5f00-89bc-887e5c052b72', 'Юлия Ш.', 'SENIORS', 8.5, '2025-09-01', 'Красиво, но есть нюансы', 'Покрытие — камни и плиты. У рифа невероятный снорклинг — свал уходит в синеву. Народу мало даже в сезон. Развлечения: доступ только на лодке, каяки.', 'Глубоко почти сразу — детям и неуверенным пловцам осторожно. Для пожилых и маломобильных тяжело: только с воды — на катере или каяке. В сентябре у берега было много медуз, пару дней купались только в бассейне.', ARRAY['+пляж', '-глубина', '+снорклинг', '+простор', '+развлечения', '-доступность', '-медузы'], '2025-09-26T12:00:00+03:00');
